python3 -c "
from warehouse.pipeline import _parse_date_dmy, _parse_date_ymd

# Test valid dates
print(_parse_date_dmy('04/05/2026'))  # Should work
print(_parse_date_dmy('31/12/2025'))  # Should work

# Test invalid dates
try:
    print(_parse_date_dmy('32/05/2026'))  # Invalid day
except ValueError as e:
    print(f'32/05/2026 error: {e}')

try:
    print(_parse_date_dmy('00/05/2026'))  # Invalid day
except ValueError as e:
    print(f'00/05/2026 error: {e}')

try:
    print(_parse_date_dmy('29/02/2025'))  # Feb 29 in non-leap year
except ValueError as e:
    print(f'29/02/2025 error: {e}')

try:
    print(_parse_date_dmy('29/02/2024'))  # Feb 29 in leap year
except ValueError as e:
    print(f'29/02/2024 error: {e}')
"
